package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.fixmer.genesis.technology.scripts.BuildSnapshot84;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.nio.file.*;import java.util.*;
/** Build -> exact side replacement -> preview -> signing. Consent/offer/COMMIT remain explicit server actions. */
public final class ScriptPublicationScreen84 extends MaredScreen {
 private final Screen previous;private final BuildSnapshot84.Snapshot snapshot;private final ScriptPublicationService84 service=new ScriptPublicationService84();private String owner,label="",side="UNSELECTED";private long ttl=86400;private EditBox root,name;private Button preview,author,open,browse,sideButton,ttlButton;private int left,w,top,scroll,maxScroll;
 public ScriptPublicationScreen84(Screen previous,BuildSnapshot84.Snapshot snapshot){super(tr("title"));this.previous=previous;this.snapshot=snapshot;var prefs=DedicatedPanelService75.preferences();owner=prefs.has("root")?prefs.get("root").getAsString():"";label="build-"+snapshot.artifact().buildId().substring(0,8);}
 private static Component tr(String key,Object...args){return Component.translatable("mared.script84."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable action){return addRenderableWidget(Button.builder(tr(key),b->action.run()).bounds(x,y,width,20).build());}
 private void collect(){if(root!=null){owner=root.getValue().trim();label=name.getValue().trim();}}
 @Override protected void init(){collect();w=Math.max(250,Math.min(680,width-24));left=(width-w)/2;root=addRenderableWidget(new EditBox(font,left+100,34,w-134,20,tr("owner")));root.setMaxLength(4096);root.setValue(owner);browse=button("browse",left+w-30,34,30,()->{collect();Path p;try{p=owner.isBlank()?minecraft.gameDirectory.toPath():Path.of(owner);}catch(Exception bad){p=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,true,p,value->{root.setValue(value.toString());collect();}));});name=addRenderableWidget(new EditBox(font,left+100,58,w-100,20,tr("label")));name.setMaxLength(40);name.setValue(label);int half=(w-4)/2;
  sideButton=button("side."+side,left,82,half,()->{collect();side=side.equals("UNSELECTED")?"BOTH":side.equals("BOTH")?"CLIENT":side.equals("CLIENT")?"SERVER":"BOTH";rebuildWidgets();});ttlButton=button("ttl."+ttl,left+half+4,82,half,()->{collect();ttl=ttl==3600?86400:ttl==86400?604800:3600;rebuildWidgets();});top=108;
  open=button("open",left,height-74,w,()->{collect();var p=DedicatedPanelService75.preferences();p.addProperty("root",owner);p.addProperty("label",service.createdLabel());DedicatedPanelService75.save(p);minecraft.setScreen(new DedicatedPanelScreen75(this));});
  preview=button("preview",left,height-50,half,()->{collect();service.run(false,owner,snapshot.directory(),side,label,ttl);});author=button("author",left+half+4,height-50,half,()->{collect();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes){collect();service.run(true,owner,snapshot.directory(),side,label,ttl);}},tr("confirm_title"),tr("confirm",label,Component.translatable("mared.script84.side."+side))));});button("back",left,height-26,w,this::onClose);tick();
 }
 @Override public void tick(){collect();root.setEditable(!service.busy());name.setEditable(!service.busy());for(Button b:new Button[]{browse,sideButton,ttlButton,preview})if(b!=null)b.active=!service.busy();preview.active=!service.busy()&&Set.of("CLIENT","SERVER","BOTH").contains(side)&&!owner.isBlank()&&label.matches("[A-Za-z0-9_-]{1,40}");author.active=service.canAuthor(owner,snapshot.directory(),side,label,ttl);open.active=service.canOpen(owner);}
 @Override public void removed(){collect();}@Override public void onClose(){if(!service.busy())minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){var out=new ArrayList<Component>();String state=service.result();out.add(tr("result."+(Set.of("IDLE","WORKING","PREVIEW","AUTHORED").contains(state)?state:"ERROR")));out.add(tr("build",snapshot.projectId(),snapshot.task(),snapshot.artifact().buildId()));out.add(tr("mods",String.join(", ",snapshot.modIds())));out.add(tr("hash",snapshot.artifact().sha256()));out.add(tr("help"));
  if(!Set.of("IDLE","WORKING","PREVIEW","AUTHORED").contains(state)){out.add(tr("error."+error(state)));out.add(Component.literal(state));}
  try{var c=service.composition();if(c.has("release"))out.add(tr("baseline",c.get("release").getAsString()));if(c.has("changes"))for(String s:List.of("client","server")){out.add(tr("changes."+s));var a=c.getAsJsonObject("changes").getAsJsonArray(s);if(a.size()==0)out.add(tr("unchanged"));for(JsonElement e:a){var item=e.getAsJsonObject();out.add(tr("change."+item.get("action").getAsString(),item.get("file").getAsString()));}}var d=service.data();if(d.has("ticket"))for(String s:List.of("client","server"))out.add(tr("count."+s,d.get(s+"Count").getAsInt(),d.get(s+"Bytes").getAsString()));if(d.has("authored")){out.add(tr("created",d.get("authored").getAsString()));out.add(tr("next"));}}catch(Exception ignored){}return out;}
 private static String error(String code){return switch(code){case "SCRIPT84_DEPENDENCIES_CHANGED","SCRIPT84_INPUTS_CHANGED","SCRIPT84_BINARY_CHANGED","SCRIPT84_SNAPSHOT_CHANGED","SCRIPT84_BUILD_REPORT_MISSING"->"stale";case "SCRIPT84_AMBIGUOUS_REPLACEMENT","SCRIPT84_PARTIAL_MOD_REPLACEMENT","SCRIPT84_DUPLICATE_MOD_ID","SCRIPT84_NAME_COLLISION"->"ambiguous";case "PUBLICATION79_BASELINE_REQUIRED","PUBLICATION83_FIRST_REQUIRED"->"baseline";case "SCRIPT84_DRAFT_CHANGED","PUBLICATION79_INPUT_CHANGED"->"preview";case "PUBLICATION79_LABEL_EXISTS"->"label";case "PUBLICATION79_UPDATE_BUSY"->"busy";default->"generic";};}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);g.drawString(font,tr("owner"),left,40,0xFFCCD0DC,false);g.drawString(font,tr("label"),left,64,0xFFCCD0DC,false);var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(Component line:lines())rows.addAll(font.split(line,w-8));int bottom=height-80,step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var row:rows){if(y+step>=top&&y<bottom)g.drawString(font,row,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
